using System;using System.IO;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;
[assembly: AssemblyVersion("5.1.0.0")]
[assembly: AssemblyFileVersion("5.1.0.0")]
class Installer {
 static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OpenAIProfilesLauncher");
 static string State=Path.Combine(Root,"installation.txt");
 static string DesktopRoot=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
 static string ProgramsRoot=Environment.GetFolderPath(Environment.SpecialFolder.Programs);
 static void SaveState(string active,string previous){string temp=State+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllLines(temp,new[]{active,previous??""});if(File.Exists(State))File.Replace(temp,State,State+".bak");else File.Move(temp,State);}
 static string Version="5.1.0";
 static string Executable(string version){if(!System.Text.RegularExpressions.Regex.IsMatch(version??"",@"^[0-9]+\.[0-9]+\.[0-9]+$"))throw new Exception("Invalid installed version.");return Path.Combine(Root,"versions",version,"OpenAIProfiles.exe");}
 static void Shortcuts(string exe){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);string folder=Path.Combine(ProgramsRoot,"OpenAI Profiles");Directory.CreateDirectory(folder);foreach(string file in new[]{Path.Combine(folder,"OpenAI Profiles.lnk"),Path.Combine(DesktopRoot,"OpenAI Profiles.lnk")}){dynamic link=shell.CreateShortcut(file);link.TargetPath=exe;link.WorkingDirectory=Path.GetDirectoryName(exe);link.Description="Independent native account launcher";link.Save();}}
 static string Install(){Directory.CreateDirectory(Root);string target=Executable(Version);Directory.CreateDirectory(Path.GetDirectoryName(target));string temp=target+".install-"+Guid.NewGuid().ToString("N");using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Launcher.exe"))using(var output=File.Create(temp)){if(stream==null)throw new Exception("Missing installer payload.");stream.CopyTo(output);}
  if(File.Exists(target)){using(var existing=File.OpenRead(target))using(var payload=File.OpenRead(temp))using(var sha=System.Security.Cryptography.SHA256.Create()){if(!sha.ComputeHash(existing).SequenceEqual(sha.ComputeHash(payload)))throw new Exception("This version is already installed with different contents. Close the installed launcher and use a new versioned release.");}File.Delete(temp);}else File.Move(temp,target);
  string previous=File.Exists(State)?File.ReadLines(State).FirstOrDefault():"";SaveState(Version,previous==Version?(File.ReadAllLines(State).Skip(1).FirstOrDefault()??""):previous??"");Shortcuts(target);return target;
 }
 static string Rollback(){if(!File.Exists(State))throw new Exception("No installed version was found.");string[] lines=File.ReadAllLines(State);if(lines.Length<2||String.IsNullOrWhiteSpace(lines[1]))throw new Exception("There is no previous installed release to roll back to.");string exe=Executable(lines[1]);if(!File.Exists(exe))throw new Exception("The previous release files are missing.");SaveState(lines[1],lines[0]);Shortcuts(exe);return exe;}
 [STAThread]static void Main(){Application.EnableVisualStyles();var f=new Form{Text="OpenAI Profiles setup · independent utility",ClientSize=new Size(520,300),BackColor=Color.FromArgb(27,27,27),ForeColor=Color.White,Font=new Font("Segoe UI",10),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,StartPosition=FormStartPosition.CenterScreen};var heading=new Label{Text="OpenAI Profiles 5.1",Font=new Font("Segoe UI",22,FontStyle.Bold),Location=new Point(28,25),Size=new Size(460,45)};f.Controls.Add(heading);var text=new Label{Text="Install for your Windows user. No administrator access needed.\r\nYour account profiles and local history stay in place.\r\nDesktop and Start menu shortcuts will be created.",Location=new Point(30,90),Size=new Size(460,80)};f.Controls.Add(text);string installed=null;var install=new Button{Text="Install / update",Location=new Point(30,205),Size=new Size(145,42)};var rollback=new Button{Text="Roll back",Location=new Point(185,205),Size=new Size(130,42)};var launch=new Button{Text="Open launcher",Location=new Point(325,205),Size=new Size(160,42),Enabled=false};install.ForeColor=Color.Black;rollback.ForeColor=Color.Black;launch.ForeColor=Color.Black;f.Controls.Add(install);f.Controls.Add(rollback);f.Controls.Add(launch);install.Click+=delegate{try{installed=Install();text.Text="Installed successfully. Your saved accounts and history were preserved.";launch.Enabled=true;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Installation could not finish");}};rollback.Click+=delegate{try{installed=Rollback();text.Text="Previous release restored. Your account profiles and history were unchanged.";launch.Enabled=true;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Rollback unavailable");}};launch.Click+=delegate{if(installed!=null)Process.Start(new ProcessStartInfo(installed){UseShellExecute=true});f.Close();};Application.Run(f);}
}
